"""Adapt only the geometric handle-reversal assertion, not node object APIs."""
import json,re
from pathlib import Path
root=Path(__file__).resolve().parents[2]
f=next(x for x in json.loads((root/'scripts/paperjs/segments.json').read_text())['fixtures'] if x['beforeReverse'])
p=f['beforeReverse'];a=p['point'];b=[x+y for x,y in zip(a,p['handleOut'])];c=[x+y for x,y in zip(a,p['handleIn'])]
def point(p):return 'svg_path.Point('+', '.join(str(float(x)) for x in p)+')'
source='''// Adapted from pinned Paper.js Segment.js, MIT license in upstream source.
// Generated by generate-segments.py. One node becomes one closed cubic:
// start/end = node; control1 = node + handleOut; control2 = node + handleIn.
// This tests geometric handle reversal, not in-place object mutation.
import gleam/float
import gleam/io
import gleam/list
import gleam/string
import svg_path
pub fn main() {
 let curve = svg_path.CubicBezier(START,OUT,IN,START)
 let sp = svg_path.subpath_assert([curve]) |> svg_path.subpath_assert_close
 let reversed = svg_path.subpath_reverse(sp)
 let assert [svg_path.CubicBezier(start: a, control1: b, control2: c, end: d)] = svg_path.subpath_segments(reversed)
 let values = [a.x,a.y,c.x -. d.x,c.y -. d.y,b.x -. a.x,b.y -. a.y]
 io.println("10:[" <> string.join(list.map(values,float.to_string),",") <> "]")
 io.println("closed:" <> string.inspect(svg_path.subpath_is_closed(reversed)))
 io.println("continuous:" <> string.inspect(a == d))
 // Supplementary identity: reversing the path twice restores its geometry.
 io.println("double_reverse:" <> string.inspect(svg_path.subpath_reverse(reversed) == sp))
}
'''.replace('START',point(a)).replace('OUT',point(b)).replace('IN',point(c))
(root/'test_paperjs/src/paper_segments_probe.gleam').write_text(source)
